    expected_amount DECIMAL(19,6),
    paid_amount DECIMAL(19,6),
    outstanding_amount DECIMAL(19,6),
    min_payment_criteria_met BOOLEAN,
    created_by BIGINT NOT NULL,
    last_modified_by BIGINT NOT NULL,
    created_on_utc TIMESTAMP WITH TIME ZONE NOT NULL,
    last_modified_on_utc TIMESTAMP WITH TIME ZONE NOT NULL,
    delinquent_days BIGINT,
    delinquent_amount DECIMAL(19,6),
    version INT NOT NULL DEFAULT 0,
    base_expected_amount DECIMAL(19,6),
    reset BOOLEAN NOT NULL DEFAULT false
);

CREATE TABLE m_wc_loan_delinquency_action (
    id BIGINT NOT NULL PRIMARY KEY,
    wc_loan_id BIGINT NOT NULL,
    action VARCHAR(128) NOT NULL,
    start_date DATE NOT NULL,
    end_date DATE NOT NULL,
    created_by BIGINT NOT NULL,
    last_modified_by BIGINT NOT NULL,
    created_on_utc TIMESTAMP WITH TIME ZONE NOT NULL,
    last_modified_on_utc TIMESTAMP WITH TIME ZONE NOT NULL,
    minimum_payment DECIMAL(19,6),
    minimum_payment_type VARCHAR(50),
    frequency INT,
    frequency_type VARCHAR(50),
    start_new_period BOOLEAN
);

CREATE TABLE m_wc_loan_range_delinquency_tag (
    id BIGINT NOT NULL PRIMARY KEY,
    created_by BIGINT NOT NULL,
    last_modified_by BIGINT NOT NULL,
    delinquency_range_id BIGINT NOT NULL,
    loan_id BIGINT NOT NULL,
    range_id BIGINT NOT NULL,
    addedon_date DATE NOT NULL,
    liftedon_date DATE,
    outstanding_amount DECIMAL(19, 6),
    version BIGINT,
    created_on_utc TIMESTAMP WITH TIME ZONE NOT NULL,
    last_modified_on_utc TIMESTAMP WITH TIME ZONE NOT NULL
);

CREATE TABLE m_wc_loan_breach_schedule (
    id BIGINT NOT NULL PRIMARY KEY,
    wc_loan_id BIGINT NOT NULL,
    period_number INT NOT NULL,
    from_date DATE NOT NULL,
    to_date DATE NOT NULL,
    number_of_days INT,
    min_payment_amount DECIMAL(19,6),
    paid_amount DECIMAL(19,6),
    outstanding_amount DECIMAL(19,6),
    near_breach BOOLEAN,
    breach BOOLEAN,
    created_by BIGINT NOT NULL,
    last_modified_by BIGINT NOT NULL,
    created_on_utc TIMESTAMP WITH TIME ZONE NOT NULL,
    last_modified_on_utc TIMESTAMP WITH TIME ZONE NOT NULL,
    reset BOOLEAN NOT NULL DEFAULT false,
    base_min_payment_amount DECIMAL(19,6)
);

CREATE TABLE m_wc_delinquency_configuration (
    id BIGINT NOT NULL PRIMARY KEY,
    created_by BIGINT NOT NULL,
    last_modified_by BIGINT NOT NULL,
    bucket_id BIGINT NOT NULL,
    frequency INT NOT NULL,
    frequency_type VARCHAR(50) NOT NULL,
    minimum_payment DECIMAL(19, 6) NOT NULL,
    minimum_payment_type VARCHAR(50) NOT NULL,
    created_on_utc TIMESTAMP WITH TIME ZONE,
    last_modified_on_utc TIMESTAMP WITH TIME ZONE
);

CREATE TABLE m_wc_breach_configuration (
    id BIGINT NOT NULL PRIMARY KEY,
    name VARCHAR(100) NOT NULL,
    breach_frequency INT,
    breach_frequency_type VARCHAR(50),
    breach_amount_calculation_type VARCHAR(50),
    breach_amount DECIMAL(19,6)
);

CREATE TABLE m_wc_near_breach (
    id BIGINT NOT NULL PRIMARY KEY,
    near_breach_name VARCHAR(100) NOT NULL,
    near_breach_frequency INT NOT NULL,
    near_breach_frequency_type VARCHAR(50) NOT NULL,
    near_breach_threshold DECIMAL(19,6) NOT NULL
);

CREATE TABLE m_wc_loan_transaction_relation (
    id BIGINT NOT NULL PRIMARY KEY,
    created_by BIGINT NOT NULL,
    last_modified_by BIGINT NOT NULL,
    from_loan_transaction_id BIGINT NOT NULL,
    to_loan_transaction_id BIGINT,
