    last_modified_on_utc DATETIME(6) NOT NULL,
    to_loan_charge_id BIGINT
);

CREATE TABLE m_wc_loan_period_payment_rate_change (
    id BIGINT NOT NULL PRIMARY KEY,
    wc_loan_id BIGINT NOT NULL,
    effective_date DATE NOT NULL,
    previous_rate DECIMAL(19,6) NOT NULL,
    new_rate DECIMAL(19,6) NOT NULL,
    is_reversed BOOLEAN NOT NULL DEFAULT false,
    reversed_on_date DATE,
    created_by BIGINT NOT NULL,
    last_modified_by BIGINT NOT NULL,
    version INT NOT NULL DEFAULT 0,
    created_on_utc TIMESTAMP WITH TIME ZONE NOT NULL,
    last_modified_on_utc TIMESTAMP WITH TIME ZONE NOT NULL,
    submitted_on_date DATE,
    calculated_annual_eir DECIMAL(19,6),
    daily_payment_amount DECIMAL(19,6),
    segment_term INT
);

CREATE TABLE m_wc_loan_charge (
    id BIGINT NOT NULL PRIMARY KEY,
    loan_id BIGINT NOT NULL,
    charge_id BIGINT NOT NULL,
    is_penalty boolean NOT NULL DEFAULT false,
    charge_time_type SMALLINT NOT NULL,
    charge_calculation_type SMALLINT NOT NULL,
    charge_payment_mode SMALLINT NOT NULL DEFAULT 0,
    amount_paid DECIMAL(19, 6),
    amount DECIMAL(19, 6),
    is_paid boolean NOT NULL DEFAULT false,
    is_active boolean NOT NULL DEFAULT true,
    due_date date,
    created_by BIGINT NOT NULL,
    last_modified_by BIGINT NOT NULL,
    external_id VARCHAR(100),
    submitted_on_date date NOT NULL,
    created_on_utc TIMESTAMP WITH TIME ZONE,
    last_modified_on_utc TIMESTAMP WITH TIME ZONE,
    amount_written_off DECIMAL(19,6) NOT NULL DEFAULT 0,
    amount_waived DECIMAL(19,6) NOT NULL DEFAULT 0
);

CREATE TABLE m_wc_loan_breach_action (
    id BIGINT NOT NULL PRIMARY KEY,
    wc_loan_id BIGINT NOT NULL,
    action VARCHAR(128) NOT NULL,
    start_date DATE NOT NULL,
    end_date DATE,
    created_by BIGINT NOT NULL,
    last_modified_by BIGINT NOT NULL,
    created_on_utc TIMESTAMP WITH TIME ZONE NOT NULL,
    last_modified_on_utc TIMESTAMP WITH TIME ZONE NOT NULL,
    minimum_payment DECIMAL(19,6),
    minimum_payment_type VARCHAR(50),
    frequency INT,
    frequency_type VARCHAR(50),
    restart_period_from_reset_date BOOLEAN
);

CREATE TABLE m_wc_loan_near_breach_action (
    id BIGINT NOT NULL PRIMARY KEY,
    wc_loan_id BIGINT NOT NULL,
    action VARCHAR(50) NOT NULL,
    threshold DECIMAL(19,6),
    frequency INT,
